select case when year(s.opened_date) < 2024 then 'before_2024' when year(s.opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, sort_array(collect_set(o.channel)) as channel_list from orders o full outer join stores s on o.store_id = s.id inner join customers c on o.customer_id = c.id group by case when year(s.opened_date) < 2024 then 'before_2024' when year(s.opened_date) = 2024 then '2024' else 'after_2024' end
